import React, { useEffect, useState } from 'react';
import { View, ScrollView, StyleSheet, I18nManager, Image, Dimensions, Pressable, } from 'react-native';
import { SearchBar } from '@rneui/base';
import { useStore } from 'react-redux';
import Icon from 'react-native-vector-icons/Ionicons';
import { getNearByLocations } from '../apis/apis';
import { Avatar, ListItem, Text } from '@rneui/themed';
import Geolocation from '@react-native-community/geolocation';
const NearByLocations = (props) => {
    const store = useStore();
    const [filtered, setFiltered] = useState([]);
    const [locations, setLocations] = useState([]);
    const [search, setSearch] = useState();
    const lang = I18nManager.isRTL ? 'ar' : 'en';
    const lables = store.getState().app.trans;
    useEffect(() => {
        Geolocation.getCurrentPosition(info => {
            let latitude = info.coords.latitude;
            let longitude = info.coords.longitude;
            let data = {
                lat: latitude,
                lng: longitude,
            }
            loadLocations(data);
        }, error => {
            loadLocations({
                lat: '',
                lng: '',
            });
        });
    }, []);
    const loadLocations = async (data) => {
        let res = await getNearByLocations(data);
        if (res.data.status) {
            setLocations(res.data.data);
            setFiltered(res.data.data);
        }
    }
    return (
        <View>
            <ScrollView>
                <SearchBar
                    value={search}
                    onFocus={() => {
                        props.navigation.navigate('SearchLocations');
                    }}
                    onChangeText={(e) => {
                        setSearch(e);
                    }}
                    placeholder={lables['search']}
                    searchIcon={
                        <Icon name='search' size={20} />
                    }
                    containerStyle={styles.searchContainer}
                    inputContainerStyle={{
                        backgroundColor: '#FFF',
                        borderRadius: 10,
                    }}
                    clearIcon={
                        <Icon name='close' size={20} />
                    }
                />
                <Text
                    style={{
                        fontSize: 21,
                        fontWeight: 'bold',
                        textAlign: 'center',
                        margin: 10,
                    }}
                >{lables['near_locations']}</Text>
                <View>
                    {
                        filtered.map((item) => {
                            return (
                                <View
                                    key={item.id}
                                    style={styles.ListItem}
                                >
                                    <View>
                                        <Image
                                            source={{ uri: item.location.location_image }}
                                            style={{
                                                width: Dimensions.get('screen').width - 30,
                                                alignSelf: 'center',
                                                height: 150,
                                                borderTopLeftRadius: 5,
                                                borderTopRightRadius: 5,
                                            }}
                                        />
                                        {
                                            item.location.distance !== undefined &&
                                            <Text
                                                style={{
                                                    backgroundColor: 'transparent',
                                                    position: 'absolute',
                                                    right: 0,
                                                    padding: 5,
                                                    fontWeight: 'bold',
                                                    color: '#FFF',
                                                }}
                                            >
                                                {item.location.distance + ' KM'}
                                            </Text>
                                        }

                                    </View>
                                    <Pressable
                                        style={{
                                            backgroundColor: '#28B3F3',
                                            borderBottomEndRadius: 5,
                                            borderBottomLeftRadius: 5,
                                        }}
                                        onPress={() => {
                                            props.navigation.navigate('ViewLocation', item);
                                        }}
                                    >
                                        <ListItem
                                            containerStyle={{
                                                backgroundColor: 'transparent',
                                                flex: 1,
                                                padding: 3,
                                            }}
                                        >
                                            <ListItem.Content>
                                                <ListItem.Title
                                                    style={{
                                                        color: '#FFF',
                                                        fontWeight: 'bold',
                                                        fontSize: 24,
                                                        marginHorizontal: 15,
                                                    }}
                                                >{lang === "en" ? item.location.location_name : item.location.location_name_ar}</ListItem.Title>
                                            </ListItem.Content>
                                            {/* <Icon name='arrow-forward' color={"#FFF"} size={42} /> */}
                                            <View
                                                style={{
                                                    borderRadius: 2,
                                                    backgroundColor: '#FFF',
                                                    marginHorizontal: 5,
                                                }}
                                            >
                                                <Text
                                                    style={{
                                                        color: '#28B3F3',
                                                        fontWeight: 'bold',
                                                        paddingHorizontal: 10,
                                                        fontSize: 16,
                                                    }}
                                                >{lables['book_now']}</Text>
                                            </View>
                                        </ListItem>
                                    </Pressable>
                                </View>
                            );
                        })
                    }
                </View>
            </ScrollView>
        </View>
    );
}
export default NearByLocations;
const styles = StyleSheet.create({
    searchContainer: {
        backgroundColor: '#FFF',
        margin: 15,
        marginTop: 30,
        borderRadius: 10,
        borderWidth: 0,
        borderTopWidth: 0,
        borderBottomWidth: 0,
        shadowColor: "#000",
        shadowOffset: {
            width: 0,
            height: 2,
        },
        shadowOpacity: 0.25,
        shadowRadius: 3.84,
        elevation: 5,
    },
    ListItem: {
        backgroundColor: '#FFF',
        margin: 15,
        borderRadius: 5,
        borderWidth: 0,
        borderTopWidth: 0,
        borderBottomWidth: 0,
        shadowColor: "#000",
        shadowOffset: {
            width: 0,
            height: 2,
        },
        shadowOpacity: 0.25,
        shadowRadius: 3.84,
        elevation: 5,
        borderBottomEndRadius: 20,
        borderBottomLeftRadius: 20,
        borderTopLeftRadius: 5,
        borderTopRightRadius: 5,

    },
    ListItemTitle: {
        fontSize: 19,
        fontWeight: 'bold'
    }
});