import React, { useRef, useState, useEffect } from 'react';
import { View, ScrollView, Image, Dimensions, StyleSheet, Alert } from 'react-native';
import { Text, SearchBar, Avatar, ListItem, Button } from '@rneui/themed';
import Sliders from './Sliders';
import NearByLocations from './../locations/NearByLocations';
import { useStore } from 'react-redux';
import { getWallet } from './../apis/apis';
import { setWallet, setScope } from './../redux/reducer';
import VIPCard from './VIPCard';
import { useFocusEffect } from '@react-navigation/native';

const Dashboard = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const user = store.getState().app.user;

    useFocusEffect(() => {
        props.navigation.getParent().setOptions({
            headerTitle: lables['home']
        });
    });
    useEffect(() => {
        props.navigation.getParent().setOptions({
            headerShown: true,
            headerRight: () => {
                return (
                    <VIPCard {...props}/>
                );
            }
        });
        getWallet(user.id)
            .then((res) => {
                store.dispatch(setScope(res.data.user.scope));
                store.dispatch(setWallet(res.data.data))
            })
            .catch(e => {
                console.log(e);
            })
    }, []);
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF'
            }}
        >
            <ScrollView showsVerticalScrollIndicator={false}>
                <View
                    style={{

                        paddingBottom: 20,
                        marginTop: 15,
                    }}
                >
                    <Sliders />
                </View>
                <ListItem
                    onPress={() => {
                        props.navigation.navigate('CurrentBookings');
                    }}
                >
                    <ListItem.Content>
                        <ListItem.Title>{lables['current_parkings']}</ListItem.Title>
                    </ListItem.Content>
                    <Button
                        onPress={() => {
                            props.navigation.navigate('CurrentBookings');
                        }}
                        title={lables['see_all']}
                        buttonStyle={{
                            padding: 0,
                            backgroundColor: '#eaf6ff',
                            elevation: 2,
                            shadowColor: "#000",
                            shadowOffset: {
                                width: 0,
                                height: 1,
                            },
                            shadowOpacity: 0.25,
                            shadowRadius: 3.50,
                            margin: 1,
                            borderColor: '#000',
                            borderWidth: 1,
                        }}
                        titleStyle={{
                            color: '#000',
                            fontSize: 14,
                        }}
                    />
                </ListItem>
                <View
                    style={{
                        // backgroundColor: '#ededed',
                        borderTopLeftRadius: 30,
                        borderTopRightRadius: 30,
                        paddingTop: 10,
                        elevation: 2,
                        shadowColor: "#000",
                        shadowOffset: {
                            width: 0,
                            height: 1,
                        },
                        shadowOpacity: 0.25,
                        shadowRadius: 3.50,
                    }}
                >
                    <NearByLocations {...props} />
                </View>
            </ScrollView>
        </View>
    );
}

export default Dashboard;
const styles = StyleSheet.create({
    avatarCard: {
        backgroundColor: '#28B3F3',
        padding: 10,
        borderWidth: 3,
        borderColor: '#FFF',
        width: 64,
        height: 64,
        borderRadius: 60,
        shadowColor: "#000",
        shadowOffset: {
            width: 0,
            height: 1,
        },
        shadowOpacity: 0.25,
        shadowRadius: 3.50,
        elevation: 2,
    },
    listItemCard: {
        margin: 10,
        marginBottom: 20,
        borderWidth: 2,
        borderColor: '#0095d5',
        borderRadius: 50,
        shadowColor: "#000",
        shadowOffset: {
            width: 0,
            height: 1,
        },
        shadowOpacity: 0.25,
        shadowRadius: 3.50,
        elevation: 2,
    }
});