import React, { useEffect, useState } from 'react';
import { ScrollView, View, Image, Dimensions, Alert } from 'react-native';
import { Text, Input, Button } from '@rneui/themed';
import { useStore } from 'react-redux';
import { Pressable } from 'react-native';
import Icon from 'react-native-vector-icons/Ionicons';
import { sendResetLink } from './../apis/apis';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { setUser } from './../redux/reducer';

const ForgotPassword = (props) => {
    const [email, setEmail] = useState("");
    const [loading, setLoading] = useState(false);
    const store = useStore();
    const lables = store.getState().app.trans;
    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['forgot_password'],
            headerBackTitle: lables['back'],
            headerBackTitleVisible:false,
            headerShadowVisible: false,
        });
    }, []);
    const handleReset = async () => {
        let data = {
            email: email,
        }
        setLoading(true);
        let res = await sendResetLink(data);
        setLoading(false);
        Alert.alert(lables['done'],lables['password_link_sent_done']);
    }
    return (
        <View
            style={{
                flex: 1,
                padding: 15,
                backgroundColor: '#FFF'
            }}
        >
            <ScrollView>
                <View>
                    <Image source={require('./../assets/images/logowhite.png')}
                        style={{
                            width: 150,
                            height: 50,
                            alignSelf: 'center',
                            margin: 30,
                        }}
                    />
                    <Text
                        style={{
                            fontSize: 20,
                            fontWeight: 'bold',
                            textAlign: 'center',
                            color: '#28B3F3',

                        }}
                    >{lables['forgot_password']}</Text>
                    <View
                        style={{

                            marginTop: 20,
                        }}
                    >

                        <Input
                            value={email}
                            onChangeText={(e) => {
                                setEmail(e)
                            }}
                            inputStyle={{
                                fontSize: 20,
                                fontWeight: 'bold',
                                marginLeft: 10,
                                marginRight: 10,
                            }}
                            inputContainerStyle={{
                                borderWidth: 1,
                                borderRadius: 5,
                                padding: 5,
                            }}
                            placeholder={lables['Email']}
                        />
                       
                    </View>
                    <Button
                        loading={loading}
                        title={lables['reset']}
                        onPress={() => {
                            handleReset();
                        }}
                    />
                    <Pressable
                        onPress={() => {
                            props.navigation.navigate('Register')
                        }}
                    >
                        <Text
                            style={{
                                padding: 10,
                                fontSize: 16,
                                textDecorationLine: 'underline',
                                fontWeight:'bold'
                            }}
                        >{lables['no_account_register']}</Text>
                    </Pressable>
                </View>
            </ScrollView>
        </View>
    );
}

export default ForgotPassword;