import React, { useEffect, useState } from 'react';
import { View, ScrollView, I18nManager, StyleSheet, Dimensions, Pressable, ActivityIndicator, Alert } from 'react-native';
import { useStore } from 'react-redux';
import { Text, ListItem, Avatar, Button, Dialog, Overlay } from '@rneui/themed';
import { getVehicles } from '../apis/apis';
import Icon from 'react-native-vector-icons/Ionicons';
import { Calendar } from 'react-native-calendars';
import { TimerPickerModal } from "react-native-timer-picker";
const BookParking = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const user = store.getState().app.user;
    const wallet = store.getState().app.wallet;
    const location = props.route.params;
    const [vehicles, setVehicles] = useState([]);
    const [vehicle, setVehicle] = useState({});
    const [startTime, setStartTime] = useState('00:00 AM');
    const [endTime, setEndTime] = useState('00:00 AM');
    const [hours, setHours] = useState('0');
    const [showVehicleDialog, setShowVehicleDialog] = useState(false);
    const [showStartTimeDialog, setShowStartTimeDialog] = useState(false);
    const [showEndTimeDialog, setShowEndTimeDialog] = useState(false);
    const [loading, setLoading] = useState(false);
    const [bookingDate, setBookingDate] = useState(new Date().toISOString().split('T')[0]);
    const lang = I18nManager.isRTL ? "ar" : "en";
    const formatTime = ({
        hours,
        minutes,
        seconds,
    }) => {
        const timeParts = [];

        if (hours !== undefined) {
            timeParts.push(hours.toString().padStart(2, "0"));
        }
        if (minutes !== undefined) {
            timeParts.push(minutes.toString().padStart(2, "0"));
        }
        if (seconds !== undefined) {
            timeParts.push(seconds.toString().padStart(2, "0"));
        }

        return timeParts.join(":");
    };
    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['book_parking'],
            headerBackTitle: lables['back'],
            headerBackTitleVisible:false,
            headerShadowVisible: false,
            headerTintColor: '#FFF',
            headerStyle: {
                backgroundColor: '#28B4F2'
            },
            headerRight: () => {
                return (
                    <Pressable
                        onPress={() => {
                            props.navigation.navigate('Home')
                        }}
                    >
                        <Icon name='home' color={"#FFF"} size={26} style={{ marginHorizontal: 20 }} />
                    </Pressable>
                );
            }
        });
        getVehicles(user.id)
            .then((res) => {
                if (res.code === 200) {
                    setVehicles(res.data.data);
                }
            })
            .catch((e) => {
                console.log(e);
            })
    }, []);
    function calculateHours(end_time) {
        const startTimeStr = startTime;
        const endTimeStr = end_time;
        if (startTimeStr.match(/^\d{2}:\d{2}:\d{2}$/) && endTimeStr.match(/^\d{2}:\d{2}:\d{2}$/)) {
            const startTime = new Date();
            const endTime = new Date();
            const startTimeParts = startTimeStr.split(":");
            startTime.setHours(parseInt(startTimeParts[0], 10));
            startTime.setMinutes(parseInt(startTimeParts[1], 10));
            startTime.setSeconds(parseInt(startTimeParts[2], 10));
            const endTimeParts = endTimeStr.split(":");
            endTime.setHours(parseInt(endTimeParts[0], 10));
            endTime.setMinutes(parseInt(endTimeParts[1], 10));
            endTime.setSeconds(parseInt(endTimeParts[2], 10));
            const timeDifference = endTime - startTime;
            let hoursDiff = Math.floor(timeDifference / 3600000);
            let minutesDiff = Math.floor((timeDifference % 3600000) / 60000);
            let secondsDiff = Math.floor(((timeDifference % 3600000) % 60000) / 1000);
            if (minutesDiff > 10) {
                hoursDiff = hoursDiff + 1;
            }
            if (hoursDiff < 0) {
                setHours(hoursDiff + 24);
            } else {
                setHours(hoursDiff);
            }
        } else {
            console.log("Invalid time format. Please use HH:MM:SS format.");
        }
    }

    function parseTime(timeString) {
        const [time, period] = timeString.split(' ');
        const [hours, minutes] = time.split(':');
        const date = new Date();
        date.setHours(parseInt(hours));
        date.setMinutes(parseInt(minutes));

        if (period?.toLowerCase() === 'pm') {
            date.setHours(date.getHours() + 12);
        }
        return date;
    }
    const checkStartTime = (start) => {
        const time1Str = start;
        const time2Str = location.start_time;
        const time1 = new Date();
        const time2 = new Date();
        const time1Parts = time1Str.split(":");
        time1.setHours(parseInt(time1Parts[0], 10));
        time1.setMinutes(parseInt(time1Parts[1], 10));
        time1.setSeconds(parseInt(time1Parts[2], 10));
        const time2Parts = time2Str.split(":");
        time2.setHours(parseInt(time2Parts[0], 10));
        time2.setMinutes(parseInt(time2Parts[1], 10));
        time2.setSeconds(parseInt(time2Parts[2], 10));
        if (time1 > time2) {
            return true;
        } else if (time1 < time2) {
            return false;
        } else {
            return true
        }
    }
    const checkEndTime = (end) => {
        const time1Str = location.close_time;
        const time2Str = end;
        const time1 = new Date();
        const time2 = new Date();
        const time1Parts = time1Str.split(":");
        time1.setHours(parseInt(time1Parts[0], 10));
        time1.setMinutes(parseInt(time1Parts[1], 10));
        time1.setSeconds(parseInt(time1Parts[2], 10));
        const time2Parts = time2Str.split(":");
        time2.setHours(parseInt(time2Parts[0], 10));
        time2.setMinutes(parseInt(time2Parts[1], 10));
        time2.setSeconds(parseInt(time2Parts[2], 10));
        if (time1 > time2) {
            return true;
        } else if (time1 < time2) {
            return false;
        } else {
            return true
        }
    }
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF',
            }}
        >
            <ScrollView>
                <Calendar
                    onDayPress={day => {
                        setBookingDate(day.dateString);
                    }}
                    minDate={new Date().toUTCString()}
                    markedDates={{
                        [bookingDate]: { selected: true, disableTouchEvent: true, }
                    }}

                />
                <View
                    style={{
                        display: 'flex',
                        flexDirection: 'row',
                        justifyContent: 'space-between',
                        marginTop: 20,
                    }}
                >
                    <View
                        style={{
                            width: Dimensions.get('screen').width / 2
                        }}
                    >
                        <Text style={{ marginHorizontal: 15, }}>{lables['start_time']}</Text>
                        <Pressable style={styles.pressableCard}
                            onPress={() => {
                                setShowStartTimeDialog(true);
                            }}
                        >
                            <Text style={{ fontWeight: 'bold', fontSize: 22, marginLeft: 10, marginRight: 10, }}>
                                {startTime}
                            </Text>
                            <Icon name='time-outline' size={32} />
                        </Pressable>
                    </View>
                    <View
                        style={{
                            width: Dimensions.get('screen').width / 2
                        }}
                    >
                        <Text style={{ marginHorizontal: 15, }}>{lables['end_time']}</Text>
                        <Pressable style={styles.pressableCard}
                            disabled={startTime === "00:00 AM" ? true : false}
                            onPress={() => {
                                setShowEndTimeDialog(true);
                            }}
                        >
                            <Text style={{ fontWeight: 'bold', fontSize: 22, marginLeft: 10, marginRight: 10, }}>
                                {endTime}
                            </Text>
                            <Icon name='time-outline' size={32} />
                        </Pressable>
                    </View>
                </View>
                <View style={styles.viewCard}>
                    <ListItem containerStyle={styles.ListItem}>
                        <ListItem.Content>
                            <ListItem.Title>{lables['hours']}</ListItem.Title>
                        </ListItem.Content>
                        <ListItem.Title>{hours + " " + lables['hours']}</ListItem.Title>
                    </ListItem>

                    <ListItem containerStyle={styles.ListItem}
                        onPress={() => {
                            setShowVehicleDialog(true);
                        }}
                    >
                        <ListItem.Content>
                            <ListItem.Title>{lables['vehicle']}</ListItem.Title>
                        </ListItem.Content>
                        <ListItem.Title>{vehicle.name}</ListItem.Title>
                        <ListItem.Chevron />
                    </ListItem>
                </View>

                <Button
                    buttonStyle={{
                        margin: 15,
                        borderRadius: 30,
                    }}
                    title={lables['confirm_parking']}
                    onPress={() => {
                        if (wallet.balance < (hours * location.hour_charge)) {
                            Alert.alert(lables['low_bal'], lables['low_bal_text'])
                        } else {
                            if (vehicle !== undefined && hours !== "0") {
                                let rate1 = (hours * location.hour_charge).toFixed(3);
                                let rate2 = (location.additional_charge_per_hour).toFixed(3);
                                let msg = lang === "ar" ? `يرجى ملاحظة أنه لمدة ${hours} ساعات سيتم محاسبتك بمبلغ ${rate1} دينار كويتي. لكل ساعة بعد الوقت المحجوز، سيتم محاسبتك بمبلغ ${rate2} دينار كويتي` : 'Please be note that for ' + hours + ' hours you will be charged with ' + (hours * location.hour_charge).toFixed(3) + ' KWD. For every 1 hour after reserved time you will be charged ' + (location.additional_charge_per_hour).toFixed(3) + ' KWD';
                                Alert.alert(
                                    lables['confirm_parking'],
                                    msg,
                                    [

                                        {
                                            text: lables['cancel'],
                                            onPress: () => console.log('Cancel Pressed'),
                                            style: 'cancel',
                                        },
                                        {
                                            text: lables['confirm'], onPress: () => {
                                                let data = {
                                                    vehicle: vehicle,
                                                    startTime: startTime,
                                                    endTime: endTime,
                                                    bookingDate: bookingDate,
                                                    location: location,
                                                    hours: hours,
                                                }
                                                props.navigation.navigate('ConfirmParking', data);
                                            }
                                        },
                                    ]
                                );
                            }
                        }

                    }}
                />
                <Overlay
                    isVisible={loading}
                >
                    <ActivityIndicator />
                </Overlay>
                <Dialog
                    isVisible={showVehicleDialog}
                    overlayStyle={{
                        height: Dimensions.get('screen').height - 450
                    }}
                >
                    <ScrollView>
                        {
                            vehicles.map((item) => {
                                return (
                                    <ListItem key={item.id} bottomDivider
                                        onPress={() => {
                                            setVehicle(item);
                                        }}
                                    >
                                        <ListItem.Content>
                                            <ListItem.Title>{item.name}</ListItem.Title>
                                        </ListItem.Content>
                                        <ListItem.CheckBox
                                            onPress={() => {
                                                setVehicle(item);
                                            }}
                                            uncheckedIcon={
                                                <Icon name='square-outline' size={22} />
                                            }
                                            checkedIcon={
                                                <Icon name='checkbox-outline' size={22} />
                                            }
                                            checked={vehicle.id === item.id}
                                        />
                                    </ListItem>
                                );
                            })
                        }
                    </ScrollView>
                    <Button
                        title={lables['select']}
                        onPress={() => {
                            setShowVehicleDialog(false);
                        }}
                    />
                </Dialog>
                <TimerPickerModal
                    visible={showStartTimeDialog}
                    hourLabel="H"
                    minuteLabel="M"
                    secondLabel="S"
                    setIsVisible={setShowStartTimeDialog}
                    onConfirm={(pickedDuration) => {
                        let formatedTime = formatTime(pickedDuration);
                        let flag = checkStartTime(formatedTime);
                        if (!flag) {
                            Alert.alert(lables['alert'], lables['mall_is_closed']);
                        } else {
                            setStartTime(formatedTime);
                            setShowStartTimeDialog(false);
                        }

                    }}
                    modalTitle={lables['start_time']}
                    confirmButtonText={lables['confirm']}
                    cancelButtonText={lables['cancel']}
                    closeOnOverlayPress
                    styles={{
                        theme: "dark",
                    }}
                />
                <TimerPickerModal
                    visible={showEndTimeDialog}
                    hourLabel="H"
                    minuteLabel="M"
                    secondLabel="S"
                    setIsVisible={setShowEndTimeDialog}
                    onConfirm={(pickedDuration) => {
                        let formatedTime = formatTime(pickedDuration);
                        let flag = checkEndTime(formatedTime);
                        if (!flag) {
                            Alert.alert('Oops', lables['mall_is_closed']);
                        } else {
                            setEndTime(formatedTime);
                            setShowEndTimeDialog(false);
                            calculateHours(formatedTime)
                        }

                    }}
                    modalTitle={lables['end_time']}
                    confirmButtonText={lables['confirm']}
                    cancelButtonText={lables['cancel']}
                    closeOnOverlayPress
                    styles={{
                        theme: "dark",
                    }}
                />
            </ScrollView>
        </View>
    );
}

export default BookParking;
const styles = StyleSheet.create({
    viewCard: {
        backgroundColor: '#FFF',
        borderRadius: 10,
        shadowColor: "#000",
        shadowOffset: {
            width: 0,
            height: 1,
        },
        shadowOpacity: 0.25,
        shadowRadius: 3.50,
        elevation: 2,
        margin: 15,
        padding: 5,
    },
    ListItem: {
        padding: 5,
    },
    pressableCard: {
        display: 'flex',
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#FFF',
        borderRadius: 10,
        shadowColor: "#000",
        shadowOffset: {
            width: 0,
            height: 1,
        },
        shadowOpacity: 0.25,
        shadowRadius: 3.50,
        elevation: 2,
        marginLeft: 15,
        marginRight: 15,
        padding: 5,
    }
});