import React, { useEffect, useState } from "react";
import { View, ScrollView, Pressable, RefreshControl } from 'react-native';
import { useStore } from "react-redux";
import { Avatar, ListItem, Text } from '@rneui/themed';
import { getVehicles } from './../apis/apis';
import Icon from 'react-native-vector-icons/Ionicons';
import { useFocusEffect } from "@react-navigation/native";
const MyVehicles = (props) => {
    const store = useStore();
    const user = store.getState().app.user;
    const lables = store.getState().app.trans;
    const [vehicles, setVehicles] = useState([]);
    const [refresh, setRefresh] = useState(false);
    useFocusEffect(() => {
        props.navigation.getParent().setOptions({
            headerTitle: lables['my_vehicles']
        });
    });
    useEffect(() => {
        getVehicles(user.id)
            .then((res) => {
                if (res.data.code === 200) {
                    setVehicles(res.data.data);
                }
            })
            .catch(() => {
                setVehicles([]);
            });
    }, []);
    const deleteVehicle = (id) => {
        console.log(id);
    }
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF',
            }}
        >
            <ScrollView showsVerticalScrollIndicator={false}
                refreshControl={
                    <RefreshControl
                        refreshing={refresh}
                        onRefresh={() => {
                            setRefresh(true)
                            getVehicles(user.id)
                                .then((res) => {
                                    if (res.data.code === 200) {
                                        setVehicles(res.data.data);
                                        setRefresh(false);
                                    }
                                })
                                .catch(() => {
                                    setVehicles([]);
                                });
                        }}
                    />
                }
            >
                <ListItem
                    containerStyle={{
                        marginTop: 20,
                    }}
                >
                    <ListItem.Content>
                        <ListItem.Title style={{ fontSize: 20 }}>
                            {lables['add_vehicle']}
                        </ListItem.Title>
                    </ListItem.Content>
                    <Pressable
                        onPress={() => {
                            props.navigation.navigate('NewVehicle')
                        }}
                    >
                        <Avatar source={require('./../assets/images/addcar.png')} size="medium" />
                    </Pressable>
                </ListItem>
                <View
                    style={{
                        margin: 10,
                    }}
                >
                    {
                        vehicles.map((item) => {
                            return (
                                <ListItem
                                    key={item.id}
                                    containerStyle={{
                                        borderWidth: 1,
                                        borderRadius: 5,
                                        shadowColor: "#000",
                                        shadowOffset: {
                                            width: 0,
                                            height: 2,
                                        },
                                        shadowOpacity: 0.25,
                                        shadowRadius: 3.84,
                                        elevation: 5,
                                        marginBottom: 15,
                                    }}
                                >
                                    <Avatar source={{ uri: item.image }} size="medium" />
                                    <ListItem.Content>
                                        <ListItem.Title>{item.name}</ListItem.Title>
                                    </ListItem.Content>
                                    <ListItem.Subtitle>{item.plate_code + '-' + item.plate_number}</ListItem.Subtitle>
                                    {/* <Pressable style={{
                                        backgroundColor: '#28B3F3',
                                        borderRadius: 50,
                                        padding: 5,
                                    }}>
                                        <Icon name="create-outline" size={26} color="#FFF" />
                                    </Pressable> */}
                                    {/* <Pressable
                                        onPress={() => {
                                            deleteVehicle(item.id)
                                        }}
                                        style={{
                                            backgroundColor: '#28B3F3',
                                            borderRadius: 50,
                                            padding: 5,
                                        }}>
                                        <Icon name="trash-outline" size={26} color="#FFF" />
                                    </Pressable> */}
                                </ListItem>
                            );
                        })
                    }
                </View>
            </ScrollView>
        </View>
    );
}

export default MyVehicles;