import React, { useEffect, useState } from 'react';
import { ActivityIndicator, View, FlatList, I18nManager, SafeAreaView, Pressable, Dimensions } from 'react-native';
import { useStore } from 'react-redux';
import Geolocation from '@react-native-community/geolocation';
import { Input, ListItem, Text, Avatar } from '@rneui/themed';
import Icon from 'react-native-vector-icons/Ionicons';
import { Image } from '@rneui/base';
import { getAllLocations } from '../apis/apis';

const SearchLocations = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const [location, setLocation] = useState({
        lat: '29.3759',
        lng: '47.9774',
    });
    const [searching, setSearching] = useState({
        status: false,
        empty: false
    });
    const [locations, setLocations] = useState([]);
    const [filtered, setFiltered] = useState([]);
    const lang = I18nManager.isRTL ? 'ar' : 'en';
    useEffect(() => {
        Geolocation.getCurrentPosition(info => {
            let latitude = info.coords.latitude;
            let longitude = info.coords.longitude;
            let data = {
                lat: latitude,
                lng: longitude,
            }
            loadLocations(data);
        }, error => {
            loadLocations({
                lat: '',
                lng: '',
            });
        });
        const loadLocations = async (data) => {
            let res = await getAllLocations(data);
            if (res.data.status) {
                setLocations(res.data.data);
                setFiltered(res.data.data);
            }
        }
        props.navigation.setOptions({
            headerTitle: lables['locations'],
            headerShadowVisible: false,
            headerStyle: {
                backgroundColor: '#28B4F2'
            },
        });
    }, []);
    const searchLocationsByName = (query) => {
        let q = query.toLowerCase();
        if (query.length === 0) {
            setLocations(filtered);
        } else {
            const searched = filtered.filter((item) => item.location.location_name.toLowerCase().includes(q) || item.location.location_name_ar.toLowerCase().includes(q));
            setLocations(searched);
        }
    }
    const renderLocation = ({ item }) => {
        return (
            <View
                style={{
                    marginBottom: 20,
                    marginHorizontal: 20,
                    backgroundColor: '#FFF',
                    borderRadius: 20,
                    shadowColor: "#CCC",
                    shadowOffset: {
                        width: 0,
                        height: 4,
                    },
                    shadowOpacity: 0.25,
                    shadowRadius: 3.50,
                    elevation: 5,
                }}
            >
                <View
                    style={{
                        display: 'flex',
                        flexDirection: 'row',
                        justifyContent: 'space-between',
                        padding: 15,
                        alignItems: 'center',

                    }}
                >

                    <View
                        style={{
                            display: 'flex',
                            flexDirection: 'row',
                            alignItems: 'center',
                            flex: 1,
                        }}
                    >
                        <Avatar
                            size='medium'
                            rounded
                            source={{ uri: item.location.location_image }}
                        />
                        <Text
                            style={{
                                fontWeight: 'bold',
                                fontSize: 22,
                                marginHorizontal: 15,
                                flexShrink: 1,
                            }}
                        >{lang === "en" ? item.location.location_name : item.location.location_name_ar}</Text>
                    </View>
                    <View
                        style={{
                            borderWidth: 1,
                            borderTopWidth: 0,
                            borderBottomWidth: 0,
                            borderRightWidth: 0,
                            paddingLeft: 10,
                            borderColor: '#CCCC'
                        }}
                    >
                        <View
                            style={{
                                borderWidth: 1,
                                borderTopWidth: 0,
                                borderRightWidth: 0,
                                borderLeftWidth: 0,
                                borderColor: '#CCC'
                            }}
                        >
                            <Text
                                style={{
                                    paddingVertical: 5,
                                    fontSize: 20,
                                    fontWeight: 'bold'
                                }}
                            >
                                {'KWD ' + item.location.hour_charge.toFixed(3)}
                            </Text>
                        </View>
                        <View
                            style={{
                                display: 'flex',
                                flexDirection: 'row',
                                alignItems: 'center',
                            }}
                        >
                            <Image source={require('./../assets/images/pin.png')} style={{
                                width: 20,
                                height: 20,
                            }} />
                            <Text
                                style={{
                                    fontWeight: 'bold',
                                    fontSize: 20,
                                    paddingVertical: 5,
                                }}
                            >{item.free_spots + ' ' + lables['available']}</Text>
                        </View>
                    </View>
                </View>
                <ListItem
                    containerStyle={{
                        backgroundColor: '#28B4F2',
                        borderBottomLeftRadius: 20,
                        borderBottomRightRadius: 20,
                        paddingVertical: 10,
                    }}
                    onPress={() => {
                        props.navigation.navigate('ViewLocation', item);
                    }}
                >
                    <ListItem.Content>


                    </ListItem.Content>
                    <View
                        style={{
                            borderRadius: 5,
                            backgroundColor: "#fff"
                        }}
                    >
                        <Text
                            style={{
                                color: '#000',
                                fontWeight: 'bold',
                                fontSize: 18,
                                paddingHorizontal: 10,

                            }}
                        >
                            {lables['book_now']}
                        </Text>
                    </View>
                </ListItem>
            </View>
        );
    }
    return (
        <View
            style={{
                flex: 1,
            }}
        >
            <View
                style={{
                    paddingBottom: 150,
                    marginTop: 10,
                }}
            >
                <Input
                    placeholder={lables['search']}
                    leftIcon={
                        <Icon name='search-outline' size={28} color={"#000"} />
                    }
                    autoFocus
                    containerStyle={{
                        height: 100,
                    }}
                    inputContainerStyle={{
                        backgroundColor: '#FFF',
                        margin: 15,
                        borderRadius: 10,
                        borderWidth: 0,
                        borderTopWidth: 0,
                        borderBottomWidth: 0,
                        shadowColor: "#000",
                        shadowOffset: {
                            width: 0,
                            height: 2,
                        },
                        shadowOpacity: 0.25,
                        shadowRadius: 3.84,
                        elevation: 5,
                        padding: 8,
                    }}
                    returnKeyType='done'
                    inputStyle={{
                        color: '#000',
                        fontWeight: 'bold'
                    }}

                    placeholderTextColor={'#CCC'}
                    onChangeText={(e) => {
                        setSearching(true);
                        searchLocationsByName(e);
                    }}
                />

                <FlatList
                    data={locations}
                    renderItem={renderLocation}
                    ListEmptyComponent={
                        <View
                            style={{
                                marginTop: '80%',
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center'
                            }}
                        >
                            {
                                searching.status &&
                                <ActivityIndicator />
                            }
                            {
                                !searching.status && searching.empty &&
                                <Text
                                    style={{
                                        textAlign: 'center',
                                        fontSize: 16,
                                        padding: 10,
                                    }}
                                >{lables['no_locations_exist_for_search']}</Text>
                            }
                            {
                                !searching.status && !searching.empty &&
                                <Text
                                    style={{
                                        textAlign: 'center',
                                        fontSize: 16,
                                        padding: 10,
                                    }}
                                >{lables['search_tip']}</Text>
                            }
                        </View>
                    }
                />
            </View>
        </View>

    );
}
export default SearchLocations;