import React, { } from "react";
import { BackHandler } from 'react-native';
import { useFocusEffect } from '@react-navigation/native';
import { createDrawerNavigator } from '@react-navigation/drawer';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import Icon from 'react-native-vector-icons/Ionicons';
import Favourites from './Favourites';
import Profile from "./Profile";
import MyVehicles from './../vehicles/MyVehicles';
import Dashboard from './Dashboard';
import Sidemenu from './Sidemenu';
import Wallet from './../wallet/Wallet';
import { useStore } from 'react-redux';

const Drawer = createDrawerNavigator();
const Tab = createBottomTabNavigator();
Icon.loadFont();
const Home = (props) => {

    useFocusEffect(
        React.useCallback(() => {
            const onBackPress = () => {
                return true;
            };
            BackHandler.addEventListener('hardwareBackPress', onBackPress);
            return () =>
                BackHandler.removeEventListener('hardwareBackPress', onBackPress);
        }, [])
    );
    return (
        <SideBar {...props} />
    );
}
const SideBar = (props) => {
    return (
        <Drawer.Navigator
            drawerContent={() => {
                return (
                    <Sidemenu {...props} />
                );
            }}
            screenOptions={{
                headerShown: true,
            }}
        >
            <Drawer.Screen name="BottomBar" component={BottomBar}
                options={{
                    headerTintColor: '#FFF',
                    headerShadowVisible: false,
                    headerStyle: {
                        backgroundColor: '#28B3F3'
                    },
                }}
            />
        </Drawer.Navigator>
    );
}
const BottomBar = () => {
    const store = useStore();
    const lables = store.getState().app.trans;
    return (
        <Tab.Navigator
            screenOptions={{
                tabBarActiveTintColor: '#000',
                tabBarInactiveTintColor: '#CCC',
                tabBarStyle: {
                    backgroundColor: "#FFF",
                },
                headerStyle: {
                    backgroundColor: 'red'
                },
                headerTintColor: '#FFF',
            }}
        >
            <Tab.Screen
                options={{
                    tabBarIcon: ({ color, size, focused }) => (
                        focused ? <Icon name="home" color={"#000"} size={28} /> : <Icon name="home-outline" size={28} color="#ccc" />
                    ),
                    headerShown: false,
                    tabBarLabel: lables['home']

                }}
                name="Dashboard"
                component={Dashboard}
            />
            <Tab.Screen
                options={{
                    tabBarIcon: ({ color, size, focused }) => (
                        focused ? <Icon name="car" color={"#000"} size={28} /> : <Icon name="car-outline" size={28} color="#CCC" />
                    ),
                    headerShown: false,
                    tabBarLabel: lables['my_vehicles']

                }}
                name="MyVehicles"
                component={MyVehicles}
            />
            <Tab.Screen
                options={{
                    tabBarIcon: ({ color, size, focused }) => (
                        focused ? <Icon name="wallet" color={"#000"} size={28} /> : <Icon name="wallet-outline" size={28} color="#CCC" />
                    ),
                    headerShown: false,
                    tabBarLabel: lables['wallet']

                }}
                name="wallet"
                component={Wallet}
            />
            <Tab.Screen
                options={{
                    tabBarIcon: ({ color, size, focused }) => (
                        focused ? <Icon name="person" color={"#000"} size={28} /> : <Icon name="person-outline" size={28} color="#CCC" />

                    ),
                    headerShown: false,
                    tabBarLabel: lables['profile']

                }}
                name="Profile"
                component={Profile}
            />
        </Tab.Navigator>
    );
}
export default Home;