import React, { useEffect, useState } from 'react';
import { ScrollView, View, Image, Dimensions, Alert } from 'react-native';
import { Text, Input, Button } from '@rneui/themed';
import { useStore } from 'react-redux';
import { Pressable } from 'react-native';
import Icon from 'react-native-vector-icons/Ionicons';
import { login } from './../apis/apis';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { setUser } from './../redux/reducer';

const Login = (props) => {
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [showPassword, setShowPassword] = useState(false);
    const store = useStore();
    const lables = store.getState().app.trans;
    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['login'],
            headerBackTitle: lables['back'],
            headerBackTitleVisible:false,
            headerShadowVisible: false,
        });
    }, []);
    const handleLogin = async () => {
        let data = {
            email: email,
            password: password,
        }
        let res = await login(data);
        if (res.data !== ""  && res.data.data !== null ) {
            AsyncStorage.setItem('_user', JSON.stringify(res.data.data));
            store.dispatch(setUser(res.data.data));
            props.navigation.navigate('Home');
        }
        else {
            Alert.alert('Error', 'Invalid Email or Password.')
        }
    }
    return (
        <View
            style={{
                flex: 1,
                padding: 15,
                backgroundColor: '#FFF'
            }}
        >
            <ScrollView>
                <View>
                    <Image source={require('./../assets/images/logowhite.png')}
                        style={{
                            width: 150,
                            height: 50,
                            alignSelf: 'center',
                            margin: 30,
                        }}
                    />
                    <Text
                        style={{
                            fontSize: 20,
                            fontWeight: 'bold',
                            textAlign: 'center',
                            color: '#28B3F3',

                        }}
                    >{lables['login']}</Text>
                    <View
                        style={{

                            marginTop: 20,
                        }}
                    >

                        <Input
                            value={email}
                            onChangeText={(e) => {
                                setEmail(e)
                            }}
                            inputStyle={{
                                fontSize: 20,
                                fontWeight: 'bold',
                                marginLeft: 10,
                                marginRight: 10,
                            }}
                            inputContainerStyle={{
                                borderWidth: 1,
                                borderRadius: 5,
                                padding: 5,
                            }}
                            placeholder={lables['Email']}
                        />
                        <Input
                            rightIcon={
                                <Pressable
                                    onPress={() => {
                                        setShowPassword(!showPassword);
                                    }}
                                >
                                    <Icon name={showPassword ? 'eye-outline' : 'eye-off-outline'} size={30} />
                                </Pressable>
                            }
                            value={password}
                            onChangeText={(e) => {
                                setPassword(e)
                            }}
                            inputStyle={{
                                fontSize: 20,
                                fontWeight: 'bold',
                                marginLeft: 10,
                                marginRight: 10,
                            }}
                            inputContainerStyle={{
                                borderWidth: 1,
                                borderRadius: 5,
                                padding: 5,
                            }}
                            placeholder={lables['password']}
                            secureTextEntry={!showPassword}
                        />
                    </View>
                    <Button
                        title={lables['login']}
                        onPress={() => {
                            handleLogin();
                        }}
                    />
                    <Pressable
                        onPress={() => {
                            props.navigation.navigate('Register')
                        }}
                    >
                        <Text
                            style={{
                                padding: 10,
                                fontSize: 16,
                                textDecorationLine: 'underline',
                                fontWeight:'bold'
                            }}
                        >{lables['no_account_register']}</Text>
                    </Pressable>
                    <Pressable
                        onPress={() => {
                            props.navigation.navigate('ForgotPassword')
                        }}
                    >
                        <Text
                            style={{
                                padding: 10,
                                fontSize: 16,
                                textDecorationLine: 'underline',
                                fontWeight:'bold'
                            }}
                        >{lables['forgot_password']}</Text>
                    </Pressable>

                </View>
            </ScrollView>
        </View>
    );
}

export default Login;