
import { ListItem, Text } from '@rneui/themed';
import React, { useState, useEffect } from 'react';
import { View, ScrollView, I18nManager, ActivityIndicator, Dimensions } from 'react-native';
import { useStore } from 'react-redux';
import Icon from 'react-native-vector-icons/Ionicons';
import { getNotifications } from '../apis/apis';
const Notifications = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const user = store.getState().app.user;
    const lang = I18nManager.isRTL ? 'ar' : 'en';
    const [loading, setLoading] = useState(true);
    const [notifications, setNotifications] = useState([]);

    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['notifications'],
            headerBackTitle: lables['back'],
            headerShadowVisible: false,
            headerBackTitleVisible:false,
            headerTintColor: '#FFF',
            headerStyle: {
                backgroundColor: '#28B4F2'
            },
        });
        loadNotifications();
    }, []);
    const loadNotifications = async () => {
        try {
            const res = await getNotifications(user.id);
            setNotifications(res.data.data);
            setLoading(false);
        } catch (error) {

        }
    }
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF',
            }}
        >
            {
                (loading === false && notifications.length === 0) &&
                <View
                    style={{
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        height: Dimensions.get('screen').height - 150,
                    }}
                >
                    <Icon name='alert-circle' size={60} color={"#28B3F3"} />
                    <Text>{lables['no_records']}</Text>
                </View>
            }
            {
                (loading === true && notifications.length === 0) &&
                <ActivityIndicator />
            }
            {
                (loading === false && notifications.length !== 0) &&
                <ScrollView
                    showsVerticalScrollIndicator={false}
                >
                    {
                        notifications.map((item, index) => {
                            return (
                                <ListItem key={index}
                                    containerStyle={{
                                        backgroundColor: '#FFF',
                                        marginVertical: 10,
                                        marginHorizontal: 10,
                                        borderRadius: 10,
                                        borderWidth: 0,
                                        borderTopWidth: 0,
                                        borderBottomWidth: 0,
                                        shadowColor: "#000",
                                        shadowOffset: {
                                            width: 0,
                                            height: 2,
                                        },
                                        shadowOpacity: 0.25,
                                        shadowRadius: 3.84,
                                        elevation: 5,

                                    }}
                                >
                                    <ListItem.Content>
                                        <ListItem.Title>
                                            {
                                                lang == "en" ? item.title : item.ar_title
                                            }
                                        </ListItem.Title>
                                        <Text>
                                            {
                                                lang == "en" ? item.description : item.ar_desc
                                            }
                                        </Text>
                                        <Text>{item.date}</Text>
                                    </ListItem.Content>
                                </ListItem>
                            );
                        })
                    }
                </ScrollView>
            }

        </View>
    );
}

export default Notifications;